package mx.com.tiendaonline;import mx.com.tiendaonline.producto.model.dto.command.ProductoCreateCommand;import mx.com.tiendaonline.producto.model.entity.Producto;import mx.com.tiendaonline.producto.model.entity.ProductoId;import mx.com.tiendaonline.producto.port.repository.ProductoRepository;import mx.com.tiendaonline.producto.service.ProductoCreateService;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.InjectMocks;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.assertEquals;import static org.junit.jupiter.api.Assertions.assertNotNull;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.when;@ExtendWith(MockitoExtension.class)public class ProductoCreateServiceTest {    @Mock    private ProductoRepository productoRepository;    @InjectMocks    private ProductoCreateService productoCreateService;    @Test    void crearProductoTest(){        ProductoCreateCommand producto= new ProductoCreateCommand(null,"xbox", BigDecimal.valueOf(9000.00),10);        Producto productoGuardado = new Producto(1L,"xbox",BigDecimal.valueOf(9000.00),10);        when (productoRepository.create(any(Producto.class))).thenReturn(productoGuardado);        Producto resultado = productoCreateService.crear(producto);        assertNotNull(resultado);        assertEquals(1L,resultado.getId());        assertEquals("xbox",resultado.getNombre());    }}